# Load all the demo pairs and test input
import os, glob, re, json

def load_demo_from_text(text):
    """Parse grids from demo text"""
    grid_pattern = re.compile(r'^(\d+)\s+(\d+)x(\d+):$')
    rows_data = []
    current_key = None
    current_rows = []

    for line in text.split('\n'):
        match = grid_pattern.match(line.strip())
        if match:
            if current_key is not None:
                rows_data.append({
                    'key': current_key,
                    'rows': current_rows
                })
            current_key = match.group(1)
            h, w = int(match.group(2)), int(match.group(3))
            current_rows = []
        elif current_key is not None and line.strip():
            current_rows.append([int(x) for x in line.strip().split()])

    if current_key is not None:
        rows_data.append({'key': current_key, 'rows': current_rows})

    return rows_data

